// EXPECT: 7
// STDOUT: same
// Two template instantiations whose mangled names are over 300 bytes and share their first 299 bytes. The back end made a
// unique name for each global with a fixed 300-byte buffer, so "NAME.1", "NAME.2", ... were all cut to the same string, which
// was always taken, and the loop that looks for a free name never ended: a header with long template names (nlohmann/json)
// hung the front end for good. The names are as long as they need to be now, and the two statics are different objects.
#include <cstdio>
template <class T> struct Tag {
  static int v;
};
template <class T> int Tag<T>::v = 0;
struct  {};
struct  {};
int main() {
  Tag<>::v = 3;
  Tag<>::v = 4;
  std::printf("%d %d\n", Tag<>::v, Tag<>::v);
  return Tag<>::v + Tag<>::v;
}
